python3 - <<'PY'
import io
p='src/index.css'
s=io.open(p,encoding='utf-8').read()
old = """@media (min-width: 1025px) and (max-width: 1399px) {
  .bottombar__hint { display: none; }
}"""
new = """@media (min-width: 1025px) and (max-width: 1399px) {
  .bottombar__hint { display: none; }

  /* The top bar wraps here too, and for the same reason: the strapline is
     allowed 46ch, which with the search field and three readouts overruns the
     row and costs 32px of height. The date it quotes is also the one the
     settings panel owns, so dropping it loses nothing a user cannot find. */
  .topbar { gap: 18px; }
  .topbar__brand p { display: none; }
}"""
assert old in s, "mid-tier block not found"
s = s.replace(old, new)
io.open(p,'w',encoding='utf-8').write(s)
print("mid tier now also unwraps the top bar")
PY
